classes.BranchScopeProbe:
public class BranchScopeProbe {
    public enum Shade { Light, Mid, Dark }
    public static Integer run() { return observe('Seed'); }
    public static Integer runFallback() { return observe('Fallback'); }
    private static Integer observe(String seed) {
        Integer observed = 0;
        for (String phase : new List<String>{seed, 'Read'}) {
            switch on phase {
                when 'Seed' { Integer shade = 3; }
                when 'Read' { observed = Shade.values().size(); }
                when else { Integer shade = 4; }
            }
        }
        return observed;
    }
}

classes.BranchScopeObservation:
@IsTest private class BranchScopeObservation {
    @IsTest static void observe() {
        System.assert(false, 'SWITCH_SCOPE_RESULT|' + JSON.serialize(new Map<String,Object>{'ordinary'=>BranchScopeProbe.run(),'fallback'=>BranchScopeProbe.runFallback()}));
    }
}

